#include <iostream>
#include <vector>
#include <cstring>
#include <climits>
#include <queue>
#include <functional>

using namespace std;

static const int N = 50;
static const int M = 50;
static const int K = 50;
static const int T = N + K + 1;
static const int N_nodes = N * T + 1;
static const int M_edges = K + (M * 2 * K + N) * (T - 1);
static const int INF = 0x3f3f3f3f;

struct Edge {
	Edge* next;
	int destination;
};

Edge adj_list[N], adj_list2[N_nodes];
Edge* buffer_ptr1 = nullptr;
Edge* buffer_ptr2 = nullptr;

int potential[N_nodes], dist_layers[N_nodes], back_edge[N_nodes];
int heap_nodes[N_nodes + 2], heap_index[N_nodes], heap_cnt;

bool heap_compare(int u, int v) {
	return potential[u] < potential[v] || (potential[u] == potential[v] && dist_layers[u] < dist_layers[v]);
}

int heap_adjust(int i) {
	i *= 2;
	if (i > heap_cnt) return 0;
	if (i < heap_cnt && heap_compare(heap_nodes[i+1], heap_nodes[i])) return i+1;
	return i;
}

void heap_sift_up(int node) {
	int idx = heap_index[node];
	int parent;
	while ((parent = idx / 2) && heap_compare(node, heap_nodes[parent])) {
		heap_nodes[heap_index[heap_nodes[parent]] = idx] = heap_nodes[parent];
		idx = parent;
	}
	heap_nodes[heap_index[node] = idx] = node;
}

void heap_sift_down(int node) {
	int idx = heap_index[node];
	int child;
	while ((child = heap_adjust(idx)) && heap_compare(heap_nodes[child], node)) {
		heap_nodes[heap_index[heap_nodes[child]] = idx] = heap_nodes[child];
		idx = child;
	}
	heap_nodes[heap_index[node] = idx] = node;
}

void heap_push(int node) {
	heap_index[node] = ++heap_cnt;
	heap_sift_up(node);
}

int heap_pop() {
	int result = heap_nodes[1];
	int last = heap_nodes[heap_cnt--];
	heap_index[last] = 1;
	heap_sift_down(last);
	return result;
}

void add_to_adj(int source, int target) {
	if (!buffer_ptr1) {
		buffer_ptr1 = (Edge*)malloc(sizeof(Edge) * (M * 2 + 1));
		buffer_ptr1--;
	}
	buffer_ptr1->destination = target;
	buffer_ptr1->next = adj_list[source].next;
	adj_list[source].next = buffer_ptr1++;
}

void add_to_graph2(int vertex, int edge_idx) {
	if (!buffer_ptr2) {
		buffer_ptr2 = (Edge*)malloc(sizeof(Edge) * (M_edges * 2 + 1));
		buffer_ptr2--;
	}
	buffer_ptr2->destination = edge_idx;
	buffer_ptr2->next = adj_list2[vertex].next;
	adj_list2[vertex].next = buffer_ptr2++;
}

int num_nodes, num_edges;
int from[ M_edges ], to[ M_edges ], XOR_uv[ M_edges ], base_cost[ M_edges ], reduced_cost[ M_edges ];
int capacity[ M_edges * 2 ];

void connect(int u, int v, int cap, int cos) {
	int h = num_edges++;
	from[h] = u;
	to[h] = v;
	XOR_uv[h] = u ^ v;
	base_cost[h] = cos;
	capacity[ h * 2 ] = cap;
	add_to_graph2(u, h * 2);
	add_to_graph2(v, h * 2 + 1);
}

void dijkstra(int source) {
	fill(potential, potential + num_nodes, INF);
	potential[source] = 0;
	heap_push(source);
	while (heap_cnt) {
		Edge* iter;
		int u = heap_pop();
		int v;
		int h, h_, dist;
		int new_layer = dist_layers[u] + 1;

		for (iter = adj_list2[u].next; iter; iter = iter->next) {
			if (capacity[ h_ = iter->destination ]) {
				h = h_ >> 1;
				dist = potential[u] + ((h_ & 1) == 0 ? reduced_cost[h] : -reduced_cost[h]);
				v = u ^ XOR_uv[h];
				if (potential[v] == INF) {
					potential[v] = dist;
					dist_layers[v] = new_layer;
					back_edge[v] = h_;
					heap_push(v);
				} else if (potential[v] > dist || (potential[v] == dist && dist_layers[v] > new_layer)) {
					potential[v] = dist;
					dist_layers[v] = new_layer;
					back_edge[v] = h_;
					heap_sift_up(v);
				}
			}
		}
	}
}

void push_flow(int source, int target) {
	int u, h, h_;
	for (u = target; u != source; u ^= XOR_uv[h]) {
		h = (h_ = back_edge[u]) >> 1;
		capacity[h_]--;
		capacity[h_ ^ 1]++;
	}
}

int min_cost_max_flow(int src, int dst) {
	int total_flow_cost, idx;
	copy(base_cost, base_cost + num_edges, reduced_cost);
	while (1) {
		dijkstra(src);
		if (potential[dst] == INF) break;
		push_flow(src, dst);
		for (idx = 0; idx < num_edges; idx++) {
			int u = from[idx], v = to[idx];
			if (potential[u] != INF && potential[v] != INF)
				reduced_cost[idx] += potential[u] - potential[v];
		}
	}
	total_flow_cost = 0;
	for (idx = 0; idx < num_edges; idx++)
		total_flow_cost += base_cost[idx] * capacity[idx * 2 + 1];
	return total_flow_cost;
}

int main() {
	vector<int> starts(K);
	int n, m, k, c, d, t, h, i, j, s, u, v, x;
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	for (h = 0; h < k; h++) {
		scanf("%d", &starts[h]);
		starts[h]--;
	}
	while (m--) {
		scanf("%d%d", &i, &j);
		i--; j--;
		add_to_adj(i, j);
		add_to_adj(j, i);
	}
	t = n + k + 1;
	num_nodes = n * t + 1;
	num_edges = 0;
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			Edge* iter;
			u = i * t + s;
			for (iter = adj_list[i].next; iter; iter = iter->next) {
				j = iter->destination;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					connect(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			u = i * t + s;
			v = u + 1;
			connect(u, v, k, i == 0 ? 0 : c);
		}
	}
	for (h = 0; h < k; h++)
		connect(num_nodes - 1, starts[h] * t + 0, 1, 0);
	printf("%d\n", min_cost_max_flow(num_nodes - 1, 0 * t + t - 1));
	return 0;
}
